import { useCallback, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
};

function normalize(tag: string): string {
  return tag.trim().replace(/\s+/g, ' ');
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(() =>
    defaultValue.map(normalize).filter((tag, index, all) => tag.length > 0 && all.indexOf(tag) === index),
  );

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  // Поле держим пустым: введённый тег сразу переезжает в список ниже, чтобы метки не дублировались.
  const handleInputChange = useCallback(
    (entered: string[]) => {
      const incoming = entered.map(normalize).filter((tag) => tag.length > 0);
      if (incoming.length === 0) return;
      const next = [...tags];
      for (const tag of incoming) {
        if (!next.some((existing) => existing.toLowerCase() === tag.toLowerCase())) next.push(tag);
      }
      if (next.length !== tags.length) commit(next);
    },
    [commit, tags],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((existing) => existing !== tag));
    },
    [commit, tags],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <span style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font)', fontSize: '14px' }}>{label}</span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={[]}
        onValueChange={handleInputChange}
      />

      {tags.length === 0 ? (
        <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font)', fontSize: '13px' }}>
          Тегов пока нет. Наберите слово и нажмите Enter — оно появится здесь.
        </span>
      ) : (
        <div
          role="list"
          aria-label={`Выбранные теги: ${tags.length}`}
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}
        >
          {tags.map((tag) => (
            <span role="listitem" key={tag.toLowerCase()}>
              <JxChip removable active onRemove={() => removeTag(tag)}>
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

